def _expand(term, levels):
    term = term.strip()
    if not term:
        raise ValueError("empty term")
    if "*" in term:
        parts = [p.strip() for p in term.split("*")]
        if len(parts) != 2:
            raise ValueError("'*' must cross exactly two sub-terms")
        left = _expand(parts[0], levels)
        right = _expand(parts[1], levels)
        both = [f"{a}:{b}" for a in left for b in right]
        return left + right + both
    if ":" in term:
        groups = [_expand(p, levels) for p in term.split(":")]
        out = [""]
        for group in groups:
            out = [f"{prefix}:{name}" if prefix else name
                   for prefix in out for name in group]
        return out
    if term.startswith("C(") and term.endswith(")"):
        name = term[2:-1].strip()
        if name not in levels:
            raise ValueError(f"no levels declared for {name!r}")
        values = levels[name]
        if len(values) < 2:
            raise ValueError(f"{name!r} has fewer than two levels")
        return [f"C({name})[T.{v}]" for v in values[1:]]
    return [term]


def design_columns(formula, levels, intercept=True):
    if "~" not in formula:
        raise ValueError("a formula needs a '~' separating response from terms")
    response, rhs = formula.split("~", 1)
    response = response.strip()
    if not response:
        raise ValueError("a formula needs a response on the left of '~'")
    columns = ["Intercept"] if intercept else []
    for term in rhs.split("+"):
        for name in _expand(term, levels):
            if name not in columns:
                columns.append(name)
    return response, columns
